'use strict';
/* Ty Bufala Mobile 0.1 — local-first. Aucune donnée d'élevage n'est envoyée sur GitHub/Render. */
let DB_NAME='ty-bufala-mobile-local-v1';
let cloud=null,sessionUser=null;
const DB_VERSION=3;
const STORES=['animals','events','sales','labelDefinitions','animalLabelAssignments','herdGroups','animalGroupAssignments'];
const app=document.getElementById('app');
const modalRoot=document.getElementById('modalRoot');
const state=Object.fromEntries(STORES.map(k=>[k,[]]));
const ui={view:'home',herdSearch:'',herdStatus:'present',herdCategory:'',salesSearch:'',animalId:null,timelineFilter:'all'};
let database,syncBatches=[];
const nowISO=()=>new Date().toISOString();
const localToday=()=>{const d=new Date(),z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}`;};
const makeID=(prefix)=>`${prefix}_${globalThis.crypto?.randomUUID?.() || (Date.now().toString(36)+'_'+Math.random().toString(36).slice(2))}`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFR=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||'')?`${s.slice(8,10)}/${s.slice(5,7)}/${s.slice(0,4)}`:'—';
const euros=cents=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format((cents||0)/100);
const cleanTag=v=>String(v||'').trim().toUpperCase().replace(/\s+/g,'');
const norm=v=>String(v||'').trim().toLocaleLowerCase('fr-FR');
const toNumber=v=>Number(String(v??'').replace(',','.'));
const dayDiff=date=>{const d=new Date(`${date}T12:00:00`),t=new Date(`${localToday()}T12:00:00`);return Number.isNaN(+d)?Infinity:Math.round((d-t)/86400000);};
const activeAnimals=()=>state.animals.filter(x=>x.status==='present');
const pendingSales=()=>state.sales.filter(x=>x.syncState!=='synced');

function dbOpen(){return new Promise((resolve,reject)=>{
 const req=indexedDB.open(DB_NAME,DB_VERSION);
 req.onupgradeneeded=()=>{const db=req.result;for(const name of [...STORES,'outbox','meta','conflicts']){if(!db.objectStoreNames.contains(name)) db.createObjectStore(name,{keyPath:'id'});}};
 req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);
});}
function dbAll(store){return new Promise((resolve,reject)=>{const tx=database.transaction(store,'readonly'),r=tx.objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbPut(store,object){return new Promise((resolve,reject)=>{const tx=database.transaction(store,'readwrite');tx.objectStore(store).put(object);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function dbPutMany(store,objects){return new Promise((resolve,reject)=>{const tx=database.transaction(store,'readwrite');for(const object of objects)tx.objectStore(store).put(object);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function reload(){for(const name of STORES) state[name]=await dbAll(name);syncBatches=await dbAll('outbox');}
async function put(store,record){await putGroup([{kind:store,data:record}]);}
async function putGroup(records){for(const r of records){if(r.kind==='animals'){const warning=TyBufalaHerdOverview.validateAnimalCategory(r.data,localToday());if(warning)throw new Error(warning);}}const combined=[...state.animals.filter(a=>!records.some(r=>r.kind==='animals'&&r.data.id===a.id)),...records.filter(r=>r.kind==='animals').map(r=>r.data)];for(const r of records){if(r.kind==='animals'&&globalThis.TyBufalaQuality){const result=TyBufalaQuality.validateAnimal(r.data,combined,localToday());if(result.errors.length)throw new Error(result.errors[0].message);}}if(!cloud)throw new Error('Connexion individuelle nécessaire.');await cloud.save(records);await reload();}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.hidden=true,3600);}
function nav(view){ui.view=view;ui.animalId=null;document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();window.scrollTo({top:0,behavior:'instant'});}
function alertDates(){const ids=new Set(activeAnimals().map(a=>a.id));return state.events.filter(e=>!e.cancelled&&ids.has(e.animalId)&&e.nextDate&&dayDiff(e.nextDate)<=30).sort((a,b)=>a.nextDate.localeCompare(b.nextDate));}
function displayAnimal(a){return a.name?.trim() || a.earTag || 'Animal sans nom';}
function animalFor(id){return state.animals.find(a=>a.id===id);}
function dateLabel(d){const days=dayDiff(d);return days<0?`En retard de ${-days} j`:days===0?'Aujourd’hui':days===1?'Demain':`Dans ${days} j`;}
function render(){if(!sessionUser)return;document.getElementById('connectionIndicator').textContent=syncBatches.some(b=>b.blocked)?'Conflit / erreur à résoudre':cloud?.running?'Synchronisation en cours…':syncBatches.length?`${syncBatches.reduce((n,b)=>n+b.operations.length,0)} opération(s) enregistrée(s) localement · en attente` :!navigator.onLine?'Hors connexion · copie locale':cloud?.error?'Erreur · intervention nécessaire':'Synchronisé avec la base commune';
 if(ui.view==='herd'&&ui.animalId) return renderAnimalDetail(ui.animalId);
 if(ui.view==='herd')return renderHerd();if(ui.view==='sales')return renderSales();if(ui.view==='data')return renderData();return renderHome();}
function ageShort(birth){if(!birth)return 'âge inconnu';const y=Number(localToday().slice(0,4))-Number(birth.slice(0,4)),m=Number(localToday().slice(5,7))-Number(birth.slice(5,7));let months=y*12+m;if(Number(localToday().slice(8,10))<Number(birth.slice(8,10)))months--;return months<0?'date à vérifier':months<24?`${months} mois`:`${Math.floor(months/12)} an${months>=24?'s':''}`;}
function plannedChecks(){return activeAnimals().filter(a=>a.sex==='F'&&a.expectedCalving&&(!a.lastCalving||a.lastCalving<a.expectedCalving))
 .map(a=>({animal:a,days:dayDiff(a.expectedCalving)})).filter(x=>x.days>=-180&&x.days<=120).sort((x,y)=>x.days-y.days);}
function childrenOf(a){return state.animals.filter(c=>c.motherId?c.motherId===a.id:c.motherTag&&cleanTag(c.motherTag)===cleanTag(a.earTag)).sort((x,y)=>(y.birthDate||'').localeCompare(x.birthDate||''));}
function renderHome(){const due=alertDates(),overview=TyBufalaHerdOverview.summarize(state.animals,localToday()),count=overview.total,pending=pendingSales().filter(s=>!s.cancelled).length;
 const plans=plannedChecks(),past=plans.filter(x=>x.days<0),upcoming=plans.filter(x=>x.days>=0);
 app.innerHTML=`<section class="hero"><p class="eyebrow">Ty Bufala · terrain</p><h1>Bonjour ${esc(sessionUser?.name||'')}</h1><p class="lead">L’essentiel de l’élevage, directement sur ton téléphone.</p></section>
 <section class="grid stats" aria-label="Indicateurs"><div class="card stat"><strong>${state.animals.length?count:'—'}</strong><span>Animaux présents</span></div><div class="card stat"><strong>${due.length+plans.length}</strong><span>Dates à contrôler</span></div><div class="card stat"><strong>${pending}</strong><span>Ventes à transmettre</span></div></section>
 ${state.animals.length===0?`<div class="note"><strong>Chargement du cheptel partagé.</strong> Connecte-toi puis synchronise. Si la base commune n’a pas encore reçu l’inventaire validé, son import doit être effectué une seule fois par l’administrateur.</div>`:''}
 <div class="note info">${activeAnimals().filter(a=>!a.birthDate||!a.sex||(!a.motherTag&&a.motherName)).length} fiche(s) avec informations à vérifier. Présents : ${activeAnimals().filter(a=>a.sex==='F').length} femelles, ${activeAnimals().filter(a=>a.sex==='M').length} mâles. Les traitements renseignés sont consultables dans les historiques.</div>
  ${state.animals.length?`<section class="home-herd" aria-label="Répartition du cheptel"><div class="home-herd-header"><h2>Le cheptel aujourd’hui</h2><button id="refreshHerd" class="btn secondary small" type="button">↻ Actualiser</button></div><div class="herd-overview-grid">${TyBufalaHerdOverview.CATEGORIES.map(c=>`<button type="button" class="herd-overview-card ${['calvedUnknown','femaleUnknown','adultMales','unknown'].includes(c.id)?'needs-review':''}" data-herd-category="${c.id}" aria-label="Voir ${c.label} : ${overview.counts[c.id]} animaux"><strong>${overview.counts[c.id]}</strong><span class="herd-overview-name">${c.label}</span><small>${c.hint}</small></button>`).join('')}</div><p class="herd-overview-caption">Total : <strong>${overview.total} animaux présents</strong>. Chaque animal figure dans une seule catégorie. ${overview.unclassified?`${overview.unclassified} fiche(s) à préciser.`:'Toutes les fiches ont une catégorie.'} Le statut tarie / en lactation et le rôle de taureau nécessitent une confirmation dans la fiche.</p><p class="herd-overview-caption">Vue locale actualisée après chaque saisie ou synchronisation. Synchronisation automatique environ toutes les 30 s quand l’application est active ; les modifications en attente apparaissent aussi ici.</p></section>`:''}
  <div class="grid tile-grid"><button class="tile" id="quickAnimal"><div><strong>Ajouter un animal</strong><small>Naissance, identification, filiation</small></div><span class="arrow">＋</span></button><button class="tile" id="quickSale"><div><strong>Enregistrer une vente</strong><small>Produits, montant TTC et règlement</small></div><span class="arrow">＋</span></button></div>
 ${plans.length?`<div class="section-head"><h2>Prévisions issues de l’inventaire</h2><span class="badge ${past.length?'warn':''}">${plans.length} à vérifier</span></div><div class="note info">Ce sont des <strong>dates prévisionnelles Excel</strong>, pas des gestations confirmées. Si un vêlage a eu lieu, ouvre la fiche et enregistre un événement « Vêlage ».</div><div class="list" style="margin-top:9px">${[...past,...upcoming].slice(0,10).map(({animal:a,days})=>`<button class="tile" data-animal="${esc(a.id)}"><div><strong>${esc(displayAnimal(a))}</strong><small>Vêlage prévu le ${dateFR(a.expectedCalving)}</small></div><span class="badge ${days<0?'warn':''}">${days<0?'À confirmer':dateLabel(a.expectedCalving)}</span></button>`).join('')}</div>`:''}
 <div class="section-head"><h2>Rappels saisis</h2>${due.length?`<span class="badge ${due.some(e=>dayDiff(e.nextDate)<0)?'warn':''}">${due.length} suivi${due.length>1?'s':''}</span>`:''}</div>
 ${due.length?`<div class="list">${due.slice(0,8).map(e=>{const a=animalFor(e.animalId),late=dayDiff(e.nextDate)<0;return `<button class="tile" data-animal="${esc(e.animalId)}"><div><strong>${esc(displayAnimal(a||{}))} · ${esc(e.type)}</strong><small>${dateFR(e.nextDate)} · ${esc(e.description||'Suivi programmé')}</small></div><span class="badge ${late?'danger':'warn'}">${esc(dateLabel(e.nextDate))}</span></button>`;}).join('')}</div>`:'<div class="empty">Aucun rappel manuel dans les 30 prochains jours.</div>'}
 <p class="help">Copie hors connexion de la base commune. Consulte Données pour les opérations en attente. Le raccordement OneDrive et Windows reste à mettre en service.</p>`;
 mountHomeWork();
 document.getElementById('quickAnimal').onclick=()=>openAnimalForm();document.getElementById('quickSale').onclick=()=>openSaleForm();
  app.querySelectorAll('[data-animal]').forEach(b=>b.onclick=()=>{nav('herd');ui.animalId=b.dataset.animal;render();});
  app.querySelectorAll('[data-herd-category]').forEach(b=>b.addEventListener('click',()=>{ui.herdCategory=b.dataset.herdCategory;ui.herdStatus='present';nav('herd');}));
  document.getElementById('refreshHerd')?.addEventListener('click',async()=>{try{await cloud?.run();await reload();render();if(cloud?.error)toast('Synchronisation à vérifier : '+cloud.error);}catch(err){toast(err.message);}});}
function renderHerd(){app.innerHTML=`<section class="hero"><p class="eyebrow">Inventaire</p><h1>Cheptel</h1><p class="lead">Retrouver une bufflonne, compléter sa fiche et suivre les dates importantes.</p></section>
 <div class="section-head"><h2>${activeAnimals().length} animaux présents</h2><button class="btn small" id="addAnimal">＋ Ajouter</button></div>
 <div class="filter-row"><input id="herdSearch" type="search" placeholder="Nom ou n° de boucle" aria-label="Rechercher un animal" value="${esc(ui.herdSearch)}"><select id="herdStatus" aria-label="Filtrer le cheptel"><option value="present" ${ui.herdStatus==='present'?'selected':''}>Présents</option><option value="sorti" ${ui.herdStatus==='sorti'?'selected':''}>Sortis</option><option value="females" ${ui.herdStatus==='females'?'selected':''}>Femelles présentes</option><option value="young" ${ui.herdStatus==='young'?'selected':''}>Jeunes (moins de 2 ans)</option><option value="male" ${ui.herdStatus==='male'?'selected':''}>Mâles présents</option><option value="all" ${ui.herdStatus==='all'?'selected':''}>Tous</option></select></div><div class="herd-category-filter"><label for="herdCategory">Profil d’élevage</label><select id="herdCategory"><option value="">Toutes catégories</option>${TyBufalaHerdOverview.CATEGORIES.map(c=>`<option value="${c.id}" ${ui.herdCategory===c.id?'selected':''}>${c.label}</option>`).join('')}</select></div><div id="herdList" class="list"></div>`;
 document.getElementById('addAnimal').onclick=()=>openAnimalForm();mountHerdWorkFilters();document.getElementById('herdSearch').oninput=e=>{ui.herdSearch=e.target.value;drawHerdList();};document.getElementById('herdStatus').onchange=e=>{ui.herdStatus=e.target.value;if(ui.herdStatus!=='present'){ui.herdCategory='';document.getElementById('herdCategory').value='';}drawHerdList();};document.getElementById('herdCategory').onchange=e=>{ui.herdCategory=e.target.value;if(ui.herdCategory)ui.herdStatus='present';document.getElementById('herdStatus').value=ui.herdStatus;drawHerdList();};drawHerdList();}
function drawHerdList(){const q=norm(ui.herdSearch),items=state.animals.filter(a=>{
  if(!herdWorkMatches(a))return false;
 if(ui.herdCategory && TyBufalaHerdOverview.classify(a,localToday())!==ui.herdCategory)return false;
 if(ui.herdStatus==='present'&&a.status!=='present')return false;if(ui.herdStatus==='sorti'&&a.status==='present')return false;if(ui.herdStatus==='females'&&(a.status!=='present'||a.sex!=='F'))return false;if(ui.herdStatus==='male'&&(a.status!=='present'||a.sex!=='M'))return false;if(ui.herdStatus==='young'&&(a.status!=='present'||!a.birthDate||dayDiff(a.birthDate)<-730))return false;
 return !q||norm(`${a.name} ${a.earTag} ${a.motherTag} ${a.motherName} ${a.fatherTag} ${a.fatherName} ${a.workNumber} ${a.notes} ${state.events.filter(e=>e.animalId===a.id).map(e=>e.type+' '+e.date+' '+e.description).join(' ')}`).includes(q);
 }).sort((a,b)=>displayAnimal(a).localeCompare(displayAnimal(b),'fr',{numeric:true}));
 document.getElementById('herdList').innerHTML=items.length?items.map(a=>`<button class="tile" data-id="${esc(a.id)}"><div><strong>${esc(displayAnimal(a))}</strong><small>N° ${esc(a.earTag)} · ${esc(a.sex==='M'?'Mâle':a.sex==='F'?'Femelle':'Sexe inconnu')} · ${dateFR(a.birthDate)} · ${esc(ageShort(a.birthDate))} ${a.status==='sorti'?'· Sorti':''}</small></div><span class="arrow">›</span></button>`).join(''):'<div class="empty">Aucun animal correspondant. Tu peux en ajouter un ou importer un fichier CSV.</div>';
 document.querySelectorAll('#herdList [data-id]').forEach(b=>b.onclick=()=>{ui.animalId=b.dataset.id;render();});mountHerdSelection();}
function renderAnimalDetail(id){const a=animalFor(id);if(!a){ui.animalId=null;return renderHerd();}
 const animalEvents=state.events.filter(x=>x.animalId===id),events=TyBufalaReproduction.timeline(animalEvents,ui.timelineFilter),repro=TyBufalaReproduction.summary(animalEvents,localToday());
 const children=childrenOf(a),mother=state.animals.find(x=>a.motherId?x.id===a.motherId:a.motherTag&&cleanTag(x.earTag)===cleanTag(a.motherTag)),father=state.animals.find(x=>a.fatherId?x.id===a.fatherId:a.fatherTag&&cleanTag(x.earTag)===cleanTag(a.fatherTag)),forecast=a.expectedCalving&&(!a.lastCalving||a.lastCalving<a.expectedCalving);
 const dataField=(key,value)=>value?`<div><span>${esc(key)}</span><strong>${esc(value)}</strong></div>`:'';
 app.innerHTML=`<button class="btn ghost" id="backHerd">‹ Retour au cheptel</button><div class="card"><div class="animal-head"><div><p class="eyebrow">Fiche animal · ${esc(ageShort(a.birthDate))}</p><h1>${esc(displayAnimal(a))}</h1><span class="badge ${a.status==='sorti'?'neutral':''}">${a.status==='sorti'?'Sorti':a.status==='archive'?'Archivé':'Présent'}</span></div><button class="btn secondary small" id="editAnimal">Modifier</button>${a.sex==='F'?'<button class="btn" id="addCalf">+ Ajouter un veau</button>':''}</div>
 <div class="divider"></div><div class="animal-meta">${dataField('Numéro national',a.earTag)}${dataField('Numéro de travail',a.workNumber)}${dataField('Sexe',a.sex==='M'?'Mâle':a.sex==='F'?'Femelle':'Sexe inconnu')}${dataField('Naissance',dateFR(a.birthDate))}${dataField('Mère',a.motherName||mother?.name||a.motherTag)}${dataField('Père',a.fatherName)}${dataField('Profil d’élevage',TyBufalaHerdOverview.CATEGORIES.find(c=>c.id===TyBufalaHerdOverview.classify(a,localToday()))?.label||'À préciser')}${dataField('Statut lactation',a.productionStatus==='lactating'?'En lactation':a.productionStatus==='dry'?'Tarie':'')}${dataField('Statut reproduction',a.reproductiveStatus==='heifer'?'Génisse confirmée':a.reproductiveStatus==='calved'?'A déjà vêlé':'')}${dataField('Dernier vêlage',a.lastCalving?dateFR(a.lastCalving):'')}${dataField('Mise à la reproduction',a.matingDate?dateFR(a.matingDate):'')}${dataField('Prévision de vêlage',a.expectedCalving?dateFR(a.expectedCalving):'')}${dataField('Sevrage',a.weaningDate?dateFR(a.weaningDate):'')}${dataField('Sortie',a.exitDate?dateFR(a.exitDate):'')}${dataField('Motif de sortie',a.exitReason)}</div>
 ${forecast?`<div class="note ${dayDiff(a.expectedCalving)<0?'':'info'}" style="margin-top:13px"><strong>Prévision Excel à confirmer :</strong> ${dateFR(a.expectedCalving)}. Ne vaut pas diagnostic de gestation. Enregistre le vêlage réel pour actualiser le suivi.</div>`:''}
 ${a.notes?`<div class="divider"></div><p style="white-space:pre-wrap">${esc(a.notes)}</p>`:''}</div>
 ${children.length?`<div class="section-head"><h2>Descendance connue (${children.length})</h2></div><div class="card">${children.map(c=>`<button class="tile" data-child="${esc(c.id)}" style="margin-bottom:5px"><div><strong>${esc(displayAnimal(c))}</strong><small>${dateFR(c.birthDate)} · ${c.status==='sorti'?'Sorti':'Présent'} · ${esc(c.earTag)}</small></div><span class="arrow">›</span></button>`).join('')}</div>`:''}
 ${father?`<button class="btn secondary" id="goFather" style="margin-top:12px">Voir le père : ${esc(displayAnimal(father))}</button>`:''}
 ${mother?`<button class="btn secondary" id="goMother" style="margin-top:12px">Voir la fiche de ${esc(displayAnimal(mother))}</button>`:''}
 ${a.sex==='F'?`<section class="card" aria-label="Carnet de reproduction"><h2>${esc(repro.label)}</h2><p class="help">${repro.date?'Dernier fait : '+dateFR(repro.date):'Aucun fait reproductif confirmé daté.'}${repro.conflict?' · Faits contradictoires à vérifier.':''}${repro.stale?' · Fait ancien, contrôle nécessaire.':''}</p><div class="animal-meta">${dataField('Dernière chaleur',dateFR(repro.heat?.date))}${dataField('Dernière saillie / IA',dateFR(repro.mating?.date))}${dataField('Dernier diagnostic',repro.diagnosis?dateFR(repro.diagnosis.date)+' · '+({positive:'pleine',negative:'vide',uncertain:'indéterminé'}[repro.diagnosis.result]||'à préciser'):'')}${dataField('Prochain contrôle',repro.next?dateFR(repro.next.nextDate):'')}</div></section>`:''}
 <div class="filter-row" aria-label="Actions terrain">${(a.sex==='F'?['Vue en chaleur','Saillie naturelle','Échographie','Vêlage','Tarissement','Mise en lactation']:[]).concat(['Traitement','Observation',a.status==='present'?'Sortie':'Entrée']).map(t=>`<button class="btn secondary small" data-quick-event="${esc(t)}">${esc(t)}</button>`).join('')}</div>
 <div class="section-head"><h2>Ligne du temps</h2><button class="btn small" id="addEvent">＋ Événement</button></div>
 <select id="timelineFilter" aria-label="Filtrer la ligne du temps">${[['all','Tous les événements'],['reproduction','Reproduction'],['health','Santé / traitements'],['production','Production'],['groups','Changements de lots']].map(([v,l])=>`<option value="${v}" ${ui.timelineFilter===v?'selected':''}>${l}</option>`).join('')}</select>
 ${events.length?`<div class="card">${events.map(e=>`<button class="tile" style="border:0;border-bottom:1px solid var(--line);border-radius:0;padding-left:0;padding-right:0" data-event="${esc(e.id)}"><div><div class="event-name">${esc(e.type)}${e.result?' · '+esc({positive:'Pleine',negative:'Vide',uncertain:'Indéterminé'}[e.result]||e.result):''}</div><p class="help">${e.confirmation==='confirmed'?'Confirmé':e.confirmation==='planned'?'Prévu':'À confirmer'}${e.author?' · '+esc(e.author):''}${e.source?' · '+esc(typeof e.source==='string'?e.source:'Source historique'):''}</p><div class="event-date">${dateFR(e.date)}${e.nextDate?' · Prochaine date : '+dateFR(e.nextDate):''}</div>${e.description?`<p class="help">${esc(e.description)}</p>`:''}${e.medication?`<p class="help">${esc(e.medication)} · ${esc(e.dose)} · ${esc(e.route)}<br>Attente lait : ${esc(e.milkWithdrawalDays??'non renseignée')} j · viande : ${esc(e.meatWithdrawalDays??'non renseignée')} j</p>`:''}</div><span class="arrow">›</span></button>`).join('')}</div>`:'<div class="empty">Aucun événement daté. Ajoute une observation, une intervention ou une date de suivi.</div>'}`;
 document.getElementById('timelineFilter').onchange=e=>{ui.timelineFilter=e.target.value;render();};
 document.getElementById('backHerd').onclick=()=>{ui.animalId=null;render();};document.getElementById('editAnimal').onclick=()=>openAnimalForm(a.id);document.getElementById('addEvent').onclick=()=>openEventForm(a.id);
 document.getElementById('addCalf')?.addEventListener('click',()=>openAnimalForm(null,a.id));
 document.getElementById('goFather')?.addEventListener('click',()=>{ui.animalId=father.id;render();});
 document.getElementById('goMother')?.addEventListener('click',()=>{ui.animalId=mother.id;render();});
 mountAnimalWork(a);mountEventHistory(a,animalEvents);
 app.querySelectorAll('[data-child]').forEach(b=>b.onclick=()=>{ui.animalId=b.dataset.child;render();});
 app.querySelectorAll('[data-quick-event]').forEach(b=>b.onclick=()=>openEventForm(a.id,null,b.dataset.quickEvent));
 app.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>openEventForm(a.id,b.dataset.event));}
function modal(title,content,saveLabel,handler){modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-top"><h2 id="modalTitle">${esc(title)}</h2><button type="button" class="close" aria-label="Fermer">×</button></div><form id="editorForm" class="form-stack">${content}<div class="modal-actions"><button type="button" class="btn secondary" id="cancelModal">Annuler</button><button type="submit" class="btn">${esc(saveLabel)}</button></div></form></section></div>`;
 document.body.style.overflow='hidden';const close=()=>{modalRoot.innerHTML='';document.body.style.overflow='';};modalRoot.querySelector('.close').onclick=close;modalRoot.querySelector('#cancelModal').onclick=close;
 modalRoot.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))close();});
 const form=document.getElementById('editorForm');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const ok=await handler(form);if(ok!==false){close();render();}}catch(err){toast(`Erreur : ${err.message}`);}finally{button.disabled=false;}});
 return {form,close};}
function openAnimalForm(id,motherId){const a=id?animalFor(id):null;const presetMother=motherId?animalFor(motherId):null;
 const motherOptions=activeAnimals().filter(x=>x.sex==='F').sort((x,y)=>displayAnimal(x).localeCompare(displayAnimal(y),'fr')).map(x=>`<option value="${esc(x.earTag)}">${esc(displayAnimal(x))} · ${esc(x.earTag)}</option>`).join('');
 modal(a?'Modifier un animal':'Nouvel animal',`<div class="form-grid"><div class="field"><label for="aTag">N° d’identification *</label><input id="aTag" name="earTag" required maxlength="32" autocomplete="off" value="${esc(a?.earTag||'')}"></div><div class="field"><label for="aName">Nom / surnom</label><input id="aName" name="name" maxlength="100" value="${esc(a?.name||'')}"></div><div class="field"><label for="aSex">Sexe</label><select id="aSex" name="sex"><option value="">Inconnu</option><option value="F" ${a?.sex==='F'?'selected':''}>Femelle</option><option value="M" ${a?.sex==='M'?'selected':''}>Mâle</option></select></div><div class="field"><label for="aBirth">Date de naissance</label><input id="aBirth" type="date" name="birthDate" value="${esc(a?.birthDate||'')}"></div>${!a?`<div class="field"><label>Nature de l’ajout</label><select name="birthMode"><option value="confirmed" ${presetMother&&presetMother.status!=='present'?'':'selected'}>Naissance réelle à confirmer</option><option value="historical" ${presetMother&&presetMother.status!=='present'?'selected':''}>Descendant historique — filiation seule</option></select></div>`:''}<div class="field"><label for="aMother">Mère (identification)</label><input id="aMother" name="motherTag" list="motherOptions" value="${esc(a?.motherTag||presetMother?.earTag||'')}"><datalist id="motherOptions">${motherOptions}</datalist></div><details class="field wide"><summary>Plus de détails</summary><div class="form-grid"><div class="field"><label>N° de travail</label><input name="workNumber" value="${esc(a?.workNumber||'')}"></div><div class="field"><label>Père (identification si connue)</label><input name="fatherTag" value="${esc(a?.fatherTag||'')}"></div><div class="field"><label>Père extérieur / filiation incertaine</label><input name="fatherName" value="${esc(a?.fatherName||'')}"></div><div class="field"><label>Mère extérieure / filiation incertaine</label><input name="motherName" value="${esc(a?.motherName||'')}"></div><div class="field"><label for="aStatus">Situation</label><select id="aStatus" name="status"><option value="present" ${a?.status!=='sorti'?'selected':''}>Présent</option><option value="sorti" ${a?.status==='sorti'?'selected':''}>Sorti du cheptel</option></select></div><div class="field"><label>Reproduction femelle</label><select name="reproductiveStatus"><option value="">À préciser</option><option value="heifer" ${a?.reproductiveStatus==='heifer'?'selected':''}>Génisse (n’a jamais vêlé)</option><option value="calved" ${a?.reproductiveStatus==='calved'?'selected':''}>A déjà vêlé</option></select></div><div class="field"><label>État de production actuel</label><select name="productionStatus"><option value="">À préciser</option><option value="lactating" ${a?.productionStatus==='lactating'?'selected':''}>En lactation</option><option value="dry" ${a?.productionStatus==='dry'?'selected':''}>Tarie</option></select></div><div class="field"><label>Rôle du mâle</label><select name="maleRole"><option value="">À préciser</option><option value="breeding_bull" ${a?.maleRole==='breeding_bull'?'selected':''}>Taureau reproducteur</option><option value="other" ${a?.maleRole==='other'?'selected':''}>Autre mâle</option></select></div><div class="field"><label>Dernier vêlage réel</label><input type="date" name="lastCalving" value="${esc(a?.lastCalving||'')}"></div><div class="field"><label>Reproduction / saillie</label><input type="date" name="matingDate" value="${esc(a?.matingDate||'')}"></div><div class="field"><label>Prévision vêlage (non confirmée)</label><input type="date" name="expectedCalving" value="${esc(a?.expectedCalving||'')}"></div><div class="field"><label>Date de sortie</label><input type="date" name="exitDate" value="${esc(a?.exitDate||'')}"></div><div class="field wide"><label>Motif de sortie</label><input name="exitReason" value="${esc(a?.exitReason||'')}"></div><div class="field wide"><label for="aNotes">Informations complémentaires</label><textarea id="aNotes" name="notes">${esc(a?.notes||'')}</textarea></div></div></details></div>`,a?'Enregistrer':'Ajouter',async form=>{
 const f=new FormData(form),earTag=cleanTag(f.get('earTag'));if(!earTag){toast('Le numéro d’identification est nécessaire.');return false;}
 if(state.animals.some(other=>other.id!==a?.id&&cleanTag(other.earTag)===earTag)){toast('Ce numéro est déjà enregistré dans le cheptel.');return false;}
 const mother=state.animals.find(x=>cleanTag(x.earTag)===cleanTag(f.get('motherTag')))||(!f.get('motherTag')?null:state.animals.find(x=>x.id===a?.motherId&&cleanTag(a.motherTag)===cleanTag(f.get('motherTag'))));
 const father=state.animals.find(x=>cleanTag(x.earTag)===cleanTag(f.get('fatherTag')))||state.animals.find(x=>x.id===a?.fatherId&&cleanTag(a.fatherTag)===cleanTag(f.get('fatherTag')));
 const record={...(a||{}),fatherId:father?.id||'',workNumber:String(f.get('workNumber')||''),fatherTag:cleanTag(f.get('fatherTag')),fatherName:String(f.get('fatherName')||''),id:a?.id||makeID('animal'),earTag,name:String(f.get('name')||'').trim(),sex:String(f.get('sex')||''),birthDate:String(f.get('birthDate')||''),motherId:mother?.id||'',motherTag:cleanTag(f.get('motherTag')),motherName:mother?.name||String(f.get('motherName')||''),status:f.get('status')==='sorti'?'sorti':'present',reproductiveStatus:String(f.get('reproductiveStatus')||''),productionStatus:String(f.get('productionStatus')||''),maleRole:String(f.get('maleRole')||''),lastCalving:String(f.get('lastCalving')||''),matingDate:String(f.get('matingDate')||''),expectedCalving:String(f.get('expectedCalving')||''),exitDate:String(f.get('exitDate')||''),exitReason:String(f.get('exitReason')||'').trim(),notes:String(f.get('notes')||'').trim(),createdAt:a?.createdAt||nowISO(),updatedAt:nowISO()};
   if((a?.productionStatus||'')!==record.productionStatus)record.productionStatusDate=record.productionStatus?localToday():'';
   const changes=[{kind:'animals',data:record}];
 if(record.status==='sorti'&&!confirm('Confirmer la sortie de cet animal ? L’historique sera conservé.'))return false;
 if(!a&&mother&&f.get('birthMode')==='confirmed'&&mother.status!=='present')throw new Error('La mère est sortie ou archivée : choisis un descendant historique, ou vérifie sa présence.');
 if(!a&&mother&&f.get('birthMode')==='confirmed'&&record.birthDate&&(!mother.lastCalving||record.birthDate>=mother.lastCalving)&&confirm('Cette naissance confirme-t-elle un vêlage de la mère le '+dateFR(record.birthDate)+' ?')){
   changes.push({kind:'animals',data:{...mother,reproductiveStatus:'calved',lastCalving:record.birthDate,updatedAt:nowISO()}});
   changes.push({kind:'events',data:{id:makeID('event'),animalId:mother.id,type:'Vêlage',confirmation:'confirmed',source:'Saisie terrain',calfId:record.id,date:record.birthDate,description:'Naissance confirmée de '+displayAnimal(record),createdAt:nowISO(),updatedAt:nowISO()}});
 }
 await putGroup(changes);
 if(a)ui.animalId=a.id;else ui.animalId=record.id;toast('Fiche animal enregistrée.');
 });}
function openEventForm(animalId,eventId,presetType){const e=state.events.find(x=>x.id===eventId);
 if(e?.cancelled){toast('Événement annulé : consulte l’historique des corrections.');return;}
 const {form,close}=modal(e?'Modifier un événement':presetType||'Nouvel événement',`<div class="form-grid"><div class="field"><label>Type d’événement</label><select name="type">${['Observation','Naissance',...TyBufalaReproduction.TYPES,'Saillie','Tarissement','Mise en lactation','Sevrage','Traitement','Vaccination','Intervention','Analyse','Maladie','Blessure','Pesée','Changement de lot','Changement de parcelle','Entrée','Vente','Transfert','Décès','Sortie','Autre'].map(t=>`<option ${(e?.type||presetType)===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Date de l’événement *</label><input type="date" name="date" ${e?.dateUnknown?'':'required'} value="${esc(e?.date||(!e?localToday():''))}"></div><div class="field"><label>Confirmation</label><select name="confirmation">${[['confirmed','Fait confirmé'],['uncertain','À confirmer / historique'],['planned','Prévu']].map(([v,l])=>`<option value="${v}" ${(e?.confirmation||(!e?'confirmed':'uncertain'))===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field" data-repro-result><label>Résultat du diagnostic</label><select name="result"><option value="">Choisir…</option>${[['positive','Pleine'],['negative','Vide'],['uncertain','Indéterminé']].map(([v,l])=>`<option value="${v}" ${e?.result===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field" data-repro-bull><label>Taureau connu (facultatif)</label><select name="bullId"><option value="">Non renseigné / extérieur</option>${state.animals.filter(a=>a.sex==='M').map(a=>`<option value="${esc(a.id)}" ${e?.bullId===a.id?'selected':''}>${esc(displayAnimal(a))} · ${esc(a.earTag)}</option>`).join('')}</select></div><div class="field"><label><input type="checkbox" name="dateUnknown" ${e?.dateUnknown?'checked':''}> Date historique inconnue</label></div><div class="field wide"><label>Détails / observation</label><textarea name="description">${esc(e?.description||'')}</textarea></div><details class="field wide" ${(e?.type||presetType)==='Traitement'?'open':''}><summary>Détails du traitement vétérinaire</summary><div class="form-grid">${['medication','dose','route','prescriber'].map((key,i)=>`<div class="field"><label>${['Médicament','Dose (avec unité)','Voie d’administration','Prescripteur'][i]}</label><input name="${key}" value="${esc(e?.[key]||'')}"></div>`).join('')}${['durationDays','milkWithdrawalDays','meatWithdrawalDays'].map((key,i)=>`<div class="field"><label>${['Durée (jours)','Attente lait (jours)','Attente viande (jours)'][i]}</label><input name="${key}" type="number" inputmode="numeric" min="0" step="1" value="${esc(e?.[key]??'')}"></div>`).join('')}</div></details><div class="field wide"><label>Prochaine date à vérifier (facultatif)</label><input type="date" name="nextDate" value="${esc(e?.nextDate||'')}"><span class="help">Cette date apparaîtra sur l’accueil à partir de 30 jours avant l’échéance, ou si elle est dépassée.</span></div></div>`,e?'Enregistrer':'Ajouter',async form=>{
 const f=new FormData(form),details={};for(const key of ['medication','dose','route','prescriber'])details[key]=String(f.get(key)||'');for(const key of ['durationDays','milkWithdrawalDays','meatWithdrawalDays'])details[key]=f.get(key)===''?null:Number(f.get(key));
 const event={...(e||{}),...details,confirmation:String(f.get('confirmation')),result:['Échographie','Diagnostic de gestation'].includes(String(f.get('type')))?String(f.get('result')||''):'',bullId:['Saillie','Saillie naturelle','Insémination','Mise avec taureau'].includes(String(f.get('type')))?String(f.get('bullId')||''):'',dateUnknown:f.get('dateUnknown')==='on',id:e?.id||makeID('event'),animalId,type:String(f.get('type')||'Observation'),date:String(f.get('date')||''),description:String(f.get('description')||'').trim(),nextDate:String(f.get('nextDate')||''),createdAt:e?.createdAt||nowISO(),updatedAt:nowISO()};
 if(event.dateUnknown)event.date='';
 if(['Échographie','Diagnostic de gestation'].includes(event.type)&&!event.result)throw new Error('Choisis le résultat du diagnostic.');
   const changes=[{kind:'events',data:event}];
   if(event.confirmation==='confirmed'&&!e && ['Tarissement','Mise en lactation'].includes(event.type)){
     const a=animalFor(animalId),nextStatus=event.type==='Tarissement'?'dry':'lactating';
     if(a?.sex==='F'&&a.status==='present'&&event.date&&event.date<=localToday()&&(!a.productionStatusDate||event.date>=a.productionStatusDate)){
       if(confirm(`Cet événement confirme-t-il que ${displayAnimal(a)} est ${nextStatus==='dry'?'actuellement tarie':'actuellement en lactation'} ?`))changes.push({kind:'animals',data:{...a,productionStatus:nextStatus,reproductiveStatus:'calved',productionStatusDate:event.date,updatedAt:nowISO()}});
     }else toast('Événement enregistré sans modifier le statut actuel (date antérieure, future ou animal non concerné).');
   }
 if(event.confirmation==='confirmed'&&event.type==='Vêlage'){
 const a=animalFor(animalId);
 if(a?.sex!=='F')throw new Error('Le vêlage doit être rattaché à une femelle.');
 if(event.date&&event.date<=localToday()&&(!a.lastCalving||event.date>=a.lastCalving)&&confirm('Confirmer le vêlage réel et actualiser la fiche de la mère ?'))changes.push({kind:'animals',data:{...a,lastCalving:event.date,reproductiveStatus:'calved',updatedAt:nowISO()}});
 }
 if(event.confirmation==='confirmed'&&!e&&['Sortie','Entrée'].includes(event.type)){
 const a=animalFor(animalId);
 if(!event.date||event.date>localToday())throw new Error('Une entrée ou sortie effective nécessite une date connue, au plus tard aujourd’hui.');
 if(event.type==='Sortie'&&!event.description)throw new Error('Précise le motif de sortie dans les détails.');
 if(a.exitDate&&event.date<a.exitDate)throw new Error('Cette date précède la dernière sortie : utilise un événement historique sans changer la présence.');
 changes.push({kind:'animals',data:{...a,status:event.type==='Sortie'?'sorti':'present',exitDate:event.type==='Sortie'?event.date:'',exitReason:event.type==='Sortie'?event.description:'',updatedAt:nowISO()}});
 }
 reconcileCalvingCorrection(e,event,changes);
 changes.push(...herdWorkCompletionChanges(event));
 await putGroup(changes);toast('Événement enregistré localement ; historique conservé.');
 });
 const refreshFields=()=>{const type=form.elements.type.value;form.querySelector('[data-repro-result]').hidden=!['Échographie','Diagnostic de gestation'].includes(type);form.querySelector('[data-repro-bull]').hidden=!['Saillie','Saillie naturelle','Insémination','Mise avec taureau'].includes(type);form.elements.date.required=!form.elements.dateUnknown.checked;form.elements.date.disabled=form.elements.dateUnknown.checked;};
 if(e){const cancel=document.createElement('button');cancel.type='button';cancel.className='btn ghost danger-text';cancel.id='cancelEvent';cancel.textContent='Annuler cet événement';form.append(cancel);cancel.onclick=async()=>{try{await cancelAnimalEvent(e);close();render();}catch(error){toast(error.message);}};}
 form.elements.type.addEventListener('change',refreshFields);form.elements.dateUnknown.addEventListener('change',refreshFields);refreshFields();}

function saleTotal(s){return s.lines.reduce((sum,line)=>sum+(Number(line.totalCents)||0),0);}
function renderSales(){const active=state.sales.filter(s=>!s.cancelled);app.innerHTML=`<section class="hero"><p class="eyebrow">Caisse terrain</p><h1>Ventes ponctuelles</h1><p class="lead">Saisir une vente au moment où elle se produit, même sans réseau.</p></section><div class="section-head"><h2>${active.length} ventes saisies</h2><button class="btn small" id="addSale">＋ Vente</button></div>
 <div class="filter-row"><input type="search" id="salesSearch" placeholder="Produit, date, client…" aria-label="Rechercher une vente" value="${esc(ui.salesSearch)}"></div><div id="salesList" class="list"></div><p class="help">Les ventes sont partagées entre les appareils. Leur intégration Windows reste distincte et doit être confirmée par un accusé de réception SQLite.</p>`;
 document.getElementById('addSale').onclick=()=>openSaleForm();document.getElementById('salesSearch').oninput=e=>{ui.salesSearch=e.target.value;drawSalesList();};drawSalesList();}
function drawSalesList(){const q=norm(ui.salesSearch);const items=state.sales.filter(s=>(!q||norm(`${s.date} ${s.client} ${s.channel} ${s.paymentMethod} ${s.lines.map(x=>x.product).join(' ')}`).includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));
 document.getElementById('salesList').innerHTML=items.length?items.map(s=>`<div class="list-item"><div><div class="name">${dateFR(s.date)} · ${esc(s.channel)}</div><div class="meta">${esc(s.lines.map(l=>l.product).join(', '))}${s.client?' · '+esc(s.client):''}<br>${esc(s.paymentMethod)} · <span class="badge warn">${s.cancelled?'Annulée · trace conservée':s._sync==='shared'?'Base commune · Windows en attente':'À transmettre'}</span></div></div><div class="right"><div class="amount">${euros(saleTotal(s))}</div><button class="btn ghost small" data-sale="${esc(s.id)}">Modifier</button></div></div>`).join(''):'<div class="empty">Aucune vente enregistrée. Ajoute une vente ponctuelle pour commencer.</div>';
 document.querySelectorAll('#salesList [data-sale]').forEach(b=>b.onclick=()=>openSaleForm(b.dataset.sale));}
function roundLine(price,qty){const total=(BigInt(price)*BigInt(qty)+500n)/1000n;if(total>BigInt(Number.MAX_SAFE_INTEGER))throw new Error('Montant trop élevé.');return Number(total);}
function parseCents(raw){const s=String(raw||'').trim().replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(s))throw new Error('Le prix TTC doit être un montant positif avec au plus 2 décimales.');const [euros,dec='']=s.split('.');const result=Number(euros)*100+Number(dec.padEnd(2,'0'));if(!Number.isSafeInteger(result))throw new Error('Prix trop élevé.');return result;}
function parseQtyMilli(raw){const s=String(raw||'').trim().replace(',','.');if(!/^\d+(\.\d{1,3})?$/.test(s))throw new Error('La quantité doit être positive (3 décimales maximum).');const [units,dec='']=s.split('.');const val=Number(units)*1000+Number(dec.padEnd(3,'0'));if(!Number.isSafeInteger(val)||val<=0)throw new Error('La quantité doit être supérieure à zéro.');return val;}
const displayQty=milli=>String(milli/1000).replace('.',',');
function saleLineHTML(line,index){const l=line||{};return `<div class="sale-line"><div class="sale-line-head"><strong>Produit ${index+1}</strong><button type="button" class="btn ghost small remove-line" aria-label="Supprimer cette ligne">Supprimer</button></div><div class="form-grid"><div class="field wide"><label>Produit *</label><input name="product" required maxlength="140" placeholder="Ex. Mozzarella 170 g" value="${esc(l.product||'')}"></div><div class="field"><label>Quantité *</label><input name="quantity" type="text" inputmode="decimal" required value="${esc(l.quantityMilli?displayQty(l.quantityMilli):'1')}"></div><div class="field"><label>Unité</label><select name="unit">${['pièce','kg','pot','lot','autre'].map(u=>`<option ${l.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>Prix unitaire TTC (€) *</label><input name="price" type="text" inputmode="decimal" required placeholder="0,00" value="${esc(Number.isInteger(l.unitPriceCents)?(l.unitPriceCents/100).toFixed(2).replace('.',','):'')}"></div><div class="field"><label>TVA (si connue)</label><select name="vatRate"><option value="">À déterminer</option>${['0','5.5','10','20'].map(v=>`<option value="${v}" ${String(l.vatRate)===v?'selected':''}>${v.replace('.',',')} %</option>`).join('')}</select></div></div></div>`;}
function openSaleForm(id){const s=state.sales.find(x=>x.id===id);if(s?.cancelled){toast('Vente annulée.');return;}
 const content=`<div class="form-grid"><div class="field"><label>Date de vente *</label><input type="date" name="date" required value="${esc(s?.date||localToday())}"></div><div class="field"><label>Lieu / canal</label><select name="channel">${['Marché','À la ferme','Livraison','Autre'].map(x=>`<option ${s?.channel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Mode de règlement</label><select name="paymentMethod">${['Espèces','Carte bancaire','Virement','Chèque','Autre'].map(x=>`<option ${s?.paymentMethod===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Client (facultatif)</label><input name="client" maxlength="120" value="${esc(s?.client||'')}"></div></div><div><h3>Produits vendus</h3><div id="lineItems" class="line-items">${(s?.lines?.length?s.lines:[{}]).map(saleLineHTML).join('')}</div><button type="button" id="addLine" class="btn secondary small" style="margin-top:8px">＋ Ajouter un produit</button></div><div class="total" id="saleTotalPreview">Total TTC : —</div><div class="field"><label>Note</label><textarea name="notes">${esc(s?.notes||'')}</textarea></div>${s?'<button class="btn ghost danger-text" type="button" id="cancelSale">Annuler cette vente</button>':''}`;
 const {form,close}=modal(s?'Modifier la vente':'Nouvelle vente',content,s?'Enregistrer':'Enregistrer la vente',async form=>{
 const f=new FormData(form),lines=[];
 for(const [i,row] of [...form.querySelectorAll('.sale-line')].entries()){
  const product=row.querySelector('[name=product]').value.trim();if(!product)throw new Error(`Nom du produit manquant (ligne ${i+1}).`);
  const quantityMilli=parseQtyMilli(row.querySelector('[name=quantity]').value),unitPriceCents=parseCents(row.querySelector('[name=price]').value);
  const rawVat=row.querySelector('[name=vatRate]').value;
  lines.push({product,quantityMilli,unit:row.querySelector('[name=unit]').value,unitPriceCents,vatRate:rawVat===''?null:Number(rawVat),totalCents:roundLine(unitPriceCents,quantityMilli)});
 }
 if(!lines.length)throw new Error('Ajoute au moins un produit.');
 const record={...(s||{}),id:s?.id||makeID('sale'),date:String(f.get('date')||localToday()),channel:String(f.get('channel')||'Autre'),paymentMethod:String(f.get('paymentMethod')||'Autre'),client:String(f.get('client')||'').trim(),notes:String(f.get('notes')||'').trim(),lines,syncState:'pending',cancelled:false,createdAt:s?.createdAt||nowISO(),updatedAt:nowISO()};
 await put('sales',record);toast('Vente sauvegardée sur le téléphone.');
 });
 const linesEl=form.querySelector('#lineItems'),preview=form.querySelector('#saleTotalPreview');
 const recalc=()=>{try{let total=0;for(const row of form.querySelectorAll('.sale-line')){const price=row.querySelector('[name=price]').value,quantity=row.querySelector('[name=quantity]').value;if(!price||!quantity){preview.textContent='Total TTC : —';return;}total+=roundLine(parseCents(price),parseQtyMilli(quantity));}preview.textContent=`Total TTC : ${euros(total)}`;}catch{preview.textContent='Total TTC : à vérifier';}};
 const reindex=()=>[...linesEl.querySelectorAll('.sale-line')].forEach((row,i)=>row.querySelector('.sale-line-head strong').textContent=`Produit ${i+1}`);
 form.querySelector('#addLine').onclick=()=>{linesEl.insertAdjacentHTML('beforeend',saleLineHTML({},linesEl.children.length));recalc();};
 linesEl.addEventListener('click',e=>{if(e.target.closest('.remove-line')){if(linesEl.children.length===1){toast('Une vente doit contenir au moins un produit.');return;}e.target.closest('.sale-line').remove();reindex();recalc();}});
 linesEl.addEventListener('input',recalc);recalc();
 if(s){form.querySelector('#cancelSale').onclick=async()=>{if(!confirm('Annuler cette vente ? Elle restera dans l’historique technique pour éviter des doublons de synchronisation.'))return;try{await put('sales',{...s,cancelled:true,syncState:'pending',updatedAt:nowISO()});close();render();toast('Vente annulée.');}catch(err){toast('Impossible d’annuler : '+err.message);}};}
}
function exportContent(filename,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function snapshot(kind){return {...Object.fromEntries(STORES.map(k=>[k,state[k]])),application:'ty-bufala-mobile',formatVersion:1,kind,exportedAt:nowISO(),source:'mobile',animals:state.animals,events:state.events,sales:state.sales};}
function downloadBackup(){exportContent(`ty-bufala-mobile-sauvegarde-${localToday()}.json`,JSON.stringify(snapshot('backup'),null,2),'application/json;charset=utf-8');toast('Sauvegarde JSON téléchargée.');}
function downloadHandoff(){const pending=state.sales.filter(x=>x.syncState!=='synced');const pack={...snapshot('ty-bufala-import'),sales:pending};exportContent(`ty-bufala-a-importer-${localToday()}.json`,JSON.stringify(pack,null,2),'application/json;charset=utf-8');toast('Fichier préparé. Import dans Ty Bufala non encore connecté.');}
function csvField(v){const s=String(v??'');return /[;\n"\r]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(csvField).join(';')).join('\r\n')+'\r\n';}
function downloadSalesCsv(){const rows=[['vente_id','date','canal','client','reglement','annulee','produit','quantite','unite','prix_unitaire_ttc_eur','montant_ttc_eur','tva_pourcent','date_modification']];
 for(const s of state.sales){for(const l of s.lines){rows.push([s.id,s.date,s.channel,s.client,s.paymentMethod,s.cancelled?'oui':'non',l.product,displayQty(l.quantityMilli),l.unit,(l.unitPriceCents/100).toFixed(2).replace('.',','),(l.totalCents/100).toFixed(2).replace('.',','),l.vatRate??'',s.updatedAt]);}}
 exportContent(`ty-bufala-ventes-${localToday()}.csv`,csv(rows),'text/csv;charset=utf-8');toast('CSV des ventes téléchargé.');}
function downloadHerdCsvTemplate(){const rows=[['boucle','nom','sexe','date_naissance','mere','statut','notes'],['FR0000000000','Exemple à remplacer','F','2025-05-21','','present','']];exportContent('modele-import-cheptel.csv',csv(rows),'text/csv;charset=utf-8');toast('Modèle CSV téléchargé : remplacer la ligne d’exemple.');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;const src=String(text).replace(/^\ufeff/,'');let delimiter=';';const first=src.split(/\r?\n/)[0]||'';if((first.match(/,/g)||[]).length>(first.match(/;/g)||[]).length)delimiter=',';
 for(let i=0;i<src.length;i++){const c=src[i];if(c==='"'){if(quoted&&src[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&src[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}
 row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(quoted)throw new Error('CSV : guillemets non fermés.');return rows;}
async function importHerdCsv(file){if(cloud)throw new Error('Import central réservé à l’administrateur après rapprochement.');const rows=parseCSV(await file.text());if(rows.length<2)throw new Error('CSV vide ou sans animaux.');const head=rows[0].map(x=>norm(x).replace(/\s+/g,'_')),
 idx=key=>head.indexOf(key),column=(r,key)=>idx(key)<0?'':String(r[idx(key)]||'').trim();
 if(idx('boucle')<0)throw new Error('La colonne « boucle » manque. Utilise le modèle fourni.');
 const incoming=[],inFile=new Set();for(const [i,r] of rows.slice(1).entries()){
  const earTag=cleanTag(column(r,'boucle'));if(!earTag)continue;if(inFile.has(earTag))throw new Error(`Doublon de boucle dans le CSV (ligne ${i+2}) : ${earTag}`);inFile.add(earTag);
  const existing=state.animals.find(a=>cleanTag(a.earTag)===earTag);
  const birthDate=column(r,'date_naissance');if(birthDate&&!/^\d{4}-\d{2}-\d{2}$/.test(birthDate))throw new Error(`Date non ISO (ligne ${i+2}) : ${birthDate}. Format attendu AAAA-MM-JJ.`);
  const sex=column(r,'sexe').toUpperCase(),status=norm(column(r,'statut'));
  incoming.push({id:existing?.id||makeID('animal'),earTag,name:column(r,'nom')||existing?.name||'',sex:sex==='M'?'M':existing?.sex||'F',birthDate:birthDate||existing?.birthDate||'',motherTag:cleanTag(column(r,'mere'))||existing?.motherTag||'',status:status==='sorti'?'sorti':status==='present'?'present':existing?.status||'present',notes:column(r,'notes')||existing?.notes||'',createdAt:existing?.createdAt||nowISO(),updatedAt:nowISO()});
 }
 if(!incoming.length)throw new Error('Aucun numéro de boucle dans ce fichier.');
 if(!confirm(`Importer ${incoming.length} animaux ? Les numéros existants seront mis à jour, sans supprimer les autres animaux.`))return;
 await dbPutMany('animals',incoming);await reload();render();toast(`${incoming.length} fiche(s) importée(s).`);
}
async function importBackup(file){if(cloud)throw new Error('Restauration centrale contrôlée requise. La sauvegarde locale n’est pas fusionnée automatiquement.');const data=JSON.parse(await file.text());if(data?.application!=='ty-bufala-mobile'||data.formatVersion!==1)throw new Error('Ce fichier ne correspond pas à une sauvegarde Ty Bufala Mobile v1.');
 for(const s of STORES){if(!Array.isArray(data[s])||data[s].some(x=>!x||typeof x!=='object'||typeof x.id!=='string'||!x.id))throw new Error(`Fichier invalide : ${s}.`);}
 if(!confirm('Fusionner cette sauvegarde avec les données de ce téléphone ? Les fiches avec le même identifiant seront remplacées si elles sont plus récentes.'))return;
 for(const store of STORES){const existing=new Map(state[store].map(x=>[x.id,x]));const updates=[];for(const item of data[store]){const current=existing.get(item.id);if(!current||String(item.updatedAt||'')>String(current.updatedAt||''))updates.push(item);}if(updates.length)await dbPutMany(store,updates);}
 await reload();render();toast('Sauvegarde fusionnée.');}
async function renderData(){
 const queue=cloud?await cloud.all('outbox'):[],conflicts=queue.filter(b=>b.blocked);let inventoryStatus;try{inventoryStatus=await cloud.request('inventory-status');}catch{}
 if(ui.view!=='data')return;
 app.innerHTML=`<section class="hero"><p class="eyebrow">Compte individuel · ${esc(sessionUser?.role)}</p><h1>Données partagées</h1><p>${esc(sessionUser?.name)} · ${esc(sessionUser?.id)}</p></section>
 <div class="card form-stack"><h2>Synchronisation entre appareils</h2><p>${queue.length} groupe(s) en attente · ${conflicts.length} conflit(s)</p><p role="status">${esc(cloud?.error||(!navigator.onLine?'Hors connexion : saisies conservées dans la file locale.':'Base commune accessible après connexion.'))}</p><button class="btn" id="syncNow">Synchroniser maintenant</button><button class="btn secondary" id="logout">Déconnecter ce compte</button></div>
 ${conflicts.map(b=>`<div class="card"><h2>Modification à vérifier</h2><p>${esc(b.blocked.error)}</p><p>Comparer chaque champ avant de choisir. La version abandonnée restera dans le journal local des conflits.</p><details><summary>Mes données et la version commune</summary><h3>Mes données</h3><pre class="conflict-data">${esc(JSON.stringify(b.operations,null,2))}</pre><h3>Version commune</h3><pre class="conflict-data">${esc(JSON.stringify(b.blocked.current||b.blocked,null,2))}</pre></details>${b.blocked.status===422||b.blocked.code==='duplicate_tag'?`<button class="btn" data-correct="${esc(b.id)}">Corriger la saisie rejetée</button>`:''}<button class="btn secondary" data-resolve="${esc(b.id)}" data-choice="local">Reprendre ma version</button><button class="btn secondary" data-resolve="${esc(b.id)}" data-choice="remote">Conserver la version commune</button></div>`).join('')}
 <div class="card"><h2>Source de l’inventaire</h2>${inventoryStatus?.imports?.length?inventoryStatus.imports.map(i=>`<p>Import central enregistré le ${esc(i.imported_at)} : ${i.report.animals} animaux identifiés.</p><details><summary>Lignes et filiations à vérifier (${(i.report.anomalies||[]).length})</summary><pre class="conflict-data">${esc(JSON.stringify(i.report.anomalies||[],null,2))}</pre></details>`).join(''):'<p>Import central non enregistré ou statut inaccessible hors connexion.</p>'}</div>
 <div class="card form-stack"><h2>Sauvegardes et raccordements</h2><button class="btn secondary" id="backup">Sauvegarder cet appareil et sa file d’attente</button><button class="btn secondary" id="centralBackup">Télécharger la sauvegarde centrale</button><button class="btn secondary" id="handoff">Exporter pour Windows (sans accusé de réception)</button><p>OneDrive : raccordement non activé. Windows : schéma réel et catalogue à vérifier. Une exportation ne signifie jamais « intégré ».</p><p>Les données de l’ancienne version locale restent dans leur stockage d’origine. Leur reprise nécessite un rapprochement avant import.</p></div>`;
 document.getElementById('syncNow').onclick=()=>cloud.run();document.getElementById('backup').onclick=async()=>{const pack={...snapshot('backup'),outbox:await cloud.all('outbox'),conflicts:await cloud.all('conflicts')};exportContent('ty-bufala-sauvegarde-'+localToday()+'.json',JSON.stringify(pack,null,2),'application/json');};
 document.getElementById('centralBackup').onclick=async()=>{try{const pack=await cloud.request('export');exportContent('ty-bufala-base-commune-'+localToday()+'.json',JSON.stringify(pack,null,2),'application/json');}catch(e){toast(e.message);}};
 document.getElementById('handoff').onclick=downloadHandoff;
 document.getElementById('logout').onclick=async()=>{if((await cloud.all('outbox')).length){toast('Synchronise ou résous les opérations avant de déconnecter ce compte.');return;}try{await cloud.request('logout',{method:'POST',body:'{}'});database.close();indexedDB.deleteDatabase(DB_NAME);localStorage.removeItem('tb-active-user');location.reload();}catch(e){toast(e.message);}};
 app.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>{const batch=conflicts.find(x=>x.id===b.dataset.correct),operation=batch.operations.find(o=>o.opId===batch.blocked.opId)||batch.operations[0];if(operation.kind==='animals')openAnimalForm(operation.data.id);else if(operation.kind==='events')openEventForm(operation.data.animalId,operation.data.id);else if(operation.kind==='sales')openSaleForm(operation.data.id);else toast('Affectation rejetée : compare les versions puis conserve la base commune avant de refaire l’action.');});
 app.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=async()=>{if(!confirm(b.dataset.choice==='local'?'Après comparaison, remplacer la version commune par les données locales de ce groupe ?':'Conserver la version commune et archiver les modifications locales liées (y compris les groupes dépendants) ?'))return;try{await cloud.resolve(b.dataset.resolve,b.dataset.choice);await reload();render();}catch(e){toast(e.message);}});
}
function showLogin(message=''){
 document.querySelector('.bottom-nav').hidden=true;
 app.innerHTML=`<section class="hero"><h1>Ton cheptel partagé</h1><p>Connecte-toi avec ton compte individuel pour retrouver l’inventaire sur cet appareil.</p></section><form id="loginForm" class="card form-stack"><div class="field"><label for="username">Identifiant individuel</label><input id="username" name="username" autocomplete="username" required></div><div class="field"><label for="password">Mot de passe</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><p role="alert" id="loginError">${esc(message)}</p><button class="btn" type="submit">Se connecter</button></form>`;
 document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const f=new FormData(e.target),response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(Object.fromEntries(f))}),data=await response.json();if(!response.ok)throw new Error(data.error);await activateSession(data);}catch(error){document.getElementById('loginError').textContent=error.message;}finally{button.disabled=false;}};
}
async function activateSession(data){
 sessionUser=data.user;localStorage.setItem('tb-active-user',JSON.stringify(sessionUser));DB_NAME='ty-bufala-cloud-'+sessionUser.id;
 database=await dbOpen();cloud=new CloudSync(database,sessionUser,data.csrf);cloud.onchange=async()=>{await reload();if(!modalRoot.childElementCount)render();};
 await reload();document.querySelector('.bottom-nav').hidden=false;render();await cloud.run();
 if(!window.tbTimer)window.tbTimer=setInterval(()=>{if(cloud&&!modalRoot.childElementCount)cloud.run();},30000);
}
async function start(){
 try{
 if(!('indexedDB' in window))throw new Error('Stockage local indisponible.');
 document.querySelectorAll('.bottom-nav button').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.view)));
 window.addEventListener('online',()=>cloud?.run());window.addEventListener('offline',render);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalRoot.childElementCount){modalRoot.innerHTML='';document.body.style.overflow='';}});
 if('serviceWorker' in navigator)await navigator.serviceWorker.register('./sw.js').catch(()=>{});
 if(!navigator.onLine){const previous=JSON.parse(localStorage.getItem('tb-active-user')||'null');if(previous){await activateSession({user:previous});return;}showLogin('Une première connexion en ligne est nécessaire.');return;}
 const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});
 if(response.ok)await activateSession(await response.json());else{const error=await response.json().catch(()=>({}));showLogin(error.error||'Connecte-toi pour charger le cheptel.');}

 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')cloud?.run();});
 }catch(error){const previous=JSON.parse(localStorage.getItem('tb-active-user')||'null');if(previous&&!sessionUser){await activateSession({user:previous});cloud.error='Serveur inaccessible : copie hors connexion, session à vérifier.';render();}else showLogin(error.message);}
}
start();
